export function ExpiryStatus({expiresOn}:{expiresOn:string}){const days=Math.ceil((new Date(`${expiresOn}T00:00:00`).getTime()-new Date(new Date().toDateString()).getTime())/86400000);const label=days<0?"Expired":days<=7?"Due within 7 days":days<=30?"Due within 30 days":"Valid";return <span className="rounded-full bg-slate-100 px-2 py-1 text-xs">{label}</span>}
