import { notFound } from "next/navigation"; import { requirePermission } from "@/lib/auth/guards"; import { createSupabaseServerClient } from "@/lib/supabase/server"; import { ExpiryStatus } from "@/components/documents/expiry-status";
export default async function DocumentDetail({params}:{params:Promise<{id:string}>}){await requirePermission("manage_documents");const {id}=await params;const s=await createSupabaseServerClient();const {data:doc}=await s.from("documents").select("id,document_type,expires_on,lifecycle_status,object_path").eq("id",id).maybeSingle();if(!doc)notFound();return <section className="mx-auto w-full max-w-2xl space-y-4 px-4 py-6"><h1 className="text-2xl font-semibold">Document detail</h1><p className="capitalize">{doc.document_type.replace("_"," ")}</p><ExpiryStatus expiresOn={doc.expires_on}/><p className="text-sm text-slate-600">Expires {doc.expires_on}</p></section>}
